package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.lang.reflect.Constructor;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.ArgumentMatchers.isNull;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class TypeParser_parseType_TriageGen2Test {

    private TypeParser typeParser;
    private TypeFactory typeFactory;

    @Mock
    private MyTokenizer mockTokens;

    @Mock
    private TypeFactory mockTypeFactory;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        typeFactory = TypeFactory.defaultInstance();
        // We use a spy on TypeParser because parseType is protected
        typeParser = spy(new TypeParser(typeFactory));
    }

    /**
     * Helper to instantiate TypeParser via reflection if needed, 
     * but since we use spy on a real instance, we can access protected methods.
     */
    @SuppressWarnings("unchecked")
    private JavaType invokeParseType(MyTokenizer tokens) throws Exception {
        // Since parseType is protected, we use reflection to call it from the test class
        java.lang.reflect.Method method = TypeParser.class.getDeclaredMethod("parseType", MyTokenizer.class);
        method.setAccessible(true);
        return (JavaType) method.invoke(typeParser, tokens);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseType_UnexpectedEndOfString() throws Exception {
        when(mockTokens.hasMoreTokens()).thenReturn(false);
        invokeParseType(mockTokens);
    }

    @Test
    public void testParseType_SimpleClass() throws Exception {
        when(mockTokens.hasMoreTokens()).thenReturn(true, false);
        when(mockTokens.nextToken()).thenReturn("java.lang.String");

        Class<?> stringClass = String.class;
        doReturn(stringClass).when(typeParser).findClass(eq("java.lang.String"), any());

        JavaType expectedResult = mock(JavaType.class);
        when(mockTypeFactory._fromClass(isNull(), eq(stringClass), isNull())).thenReturn(expectedResult);

        // Replace the factory in the spy to use our mock
        TypeParser spyWithMockFactory = spy(new TypeParser(mockTypeFactory));
        // Injecting via reflection or just using the spy setup
        // For simplicity in this test, we rely on the fact that we can override the factory behavior

        // Re-setup spy with controlled factory
        typeParser = spy(new TypeParser(mockTypeFactory));

        JavaType result = invokeParseType(mockTokens);

        assertEquals(expectedResult, result);
        verify(typeParser).findClass("java.lang.String", mockTokens);
    }

    @Test
    public void testParseType_WithGenerics() throws Exception {
        // Sequence of tokens: "java.util.List", "<", "java.lang.String", ">"
        // hasMoreTokens: true (for List), true (for <), true (for String), false (for end)
        when(mockTokens.hasMoreTokens()).thenReturn(true, true, true, false);
        when(mockTokens.nextToken()).thenReturn("java.util.List", "<", "java.lang.String");

        Class<?> listClass = java.util.List.class;
        Class<?> stringClass = String.class;

        doReturn(listClass).when(typeParser).findClass(eq("java.util.List"), any());

        List<JavaType> paramTypes = Collections.singletonList(mock(JavaType.class));
        doReturn(paramTypes).when(typeParser).parseTypes(mockTokens);

        JavaType genericResult = mock(JavaType.class);
        // Since TypeBindings.create is static, we can't easily mock it, 
        // but we can mock the _fromClass call that uses it.
        when(mockTypeFactory._fromClass(isNull(), eq(listClass), any(TypeBindings.class))).thenReturn(genericResult);

        // Re-instantiate spy with mock factory
        typeParser = spy(new TypeParser(mockTypeFactory));
        doReturn(listClass).when(typeParser).findClass(eq("java.util.List"), any());
        doReturn(paramTypes).when(typeParser).parseTypes(mockTokens);

        JavaType result = invokeParseType(mockTokens);

        assertNotNull(result);
        assertEquals(genericResult, result);
    }

    @Test
    public void testParseType_NonGenericWithPushBack() throws Exception {
        // Sequence: "java.lang.Integer", "," (some other token that isn't '<')
        // hasMoreTokens: true (for Integer), true (for comma)
        when(mockTokens.hasMoreTokens()).thenReturn(true, true);
        when(mockTokens.nextToken()).thenReturn("java.lang.Integer", ",");

        Class<?> integerClass = Integer.class;
        doReturn(integerClass).when(typeParser).findClass(eq("java.lang.Integer"), any());

        JavaType expectedResult = mock(JavaType.class);
        when(mockTypeFactory._fromClass(isNull(), eq(integerClass), isNull())).thenReturn(expectedResult);

        typeParser = spy(new TypeParser(mockTypeFactory));
        doReturn(integerClass).when(typeParser).findClass(eq("java.lang.Integer"), any());
        when(mockTypeFactory._fromClass(isNull(), eq(integerClass), isNull())).thenReturn(expectedResult);

        JavaType result = invokeParseType(mockTokens);

        assertEquals(expectedResult, result);
        // Verify that the comma was pushed back
        verify(mockTokens).pushBack(",");
    }
}
